begin;
create function pg_temp.assert_true(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERT: %',message;end if;end;$$;
create function pg_temp.denied(command text) returns void language plpgsql as $$begin
 begin execute command;exception when insufficient_privilege or check_violation then return;end;
 raise exception 'Expected permission denial: %',command;
end;$$;
insert into auth.users(id) values('10000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000002'),('10000000-0000-4000-8000-000000000003'),('10000000-0000-4000-8000-000000000004');
